mapper.update:
UPDATE PUSH_SUB_TB
   SET STATE  = 'D',
       UDT_DT = NOW()
 WHERE ENDPOINT_HASH = #{endpointHash}
   AND MEM_ID        = #{memId}

mapper.select:
SELECT FROM PUSH_SUB_TB WHERE STATE = 'I' AND MEM_ID IN
#{memId}
ORDER BY MEM_ID, PUSH_SEQ

SELECT FROM PUSH_SUB_TB WHERE STATE = 'I'
AND MEM_ID != #{exceptMemId}
ORDER BY MEM_ID, PUSH_SEQ
